public void tick(long cd) {
		boolean ticked = false;
		for (StaffSpellInfo spell : getSpells()) {
			if (spell.tick()) {
				ticked = true;
			}
			if (spell.validate(cd)) {
				ticked = true;
			}
		}
		if (ticked) {
			saveToStack();
		}
	}

